import { Table, Group, Text, ActionIcon, Tooltip } from "@mantine/core";
import { IconPlayerPlay, IconDownload, IconShare } from "@tabler/icons-react";
import { OrderFE } from "../../../types/order.types"; // Tu tipo de frontend para la orden
import { OrderStatusBadge } from "./OrderStatusBadge";
import dayjs from "dayjs"; // npm install dayjs

interface OrderRowProps {
  order: OrderFE;
  onPlay: (order: OrderFE) => void;
}

export function OrderRow({ order, onPlay }: OrderRowProps) {
  const isPlayable = order.status === "COMPLETED" && order.finalVideoUrl;

  return (
    <Table.Tr>
      <Table.Td>
        <Text fz="sm" fw={500}>
          {order.topic}
        </Text>
        <Text fz="xs" c="dimmed">
          {order.educationalStageSelected}{" "}
          {order.subdivisionGradeSelected &&
            ` - ${order.subdivisionGradeSelected}`}
        </Text>
      </Table.Td>
      <Table.Td>
        <Text fz="sm">{dayjs(order.createdAt).format("DD/MM/YYYY HH:mm")}</Text>
      </Table.Td>
      <Table.Td>
        <OrderStatusBadge status={order.status} />
      </Table.Td>
      <Table.Td>
        <Group gap="xs" justify="flex-end">
          <Tooltip label="Ver Video">
            <ActionIcon
              onClick={() => onPlay(order)}
              disabled={!isPlayable}
              variant="light"
              color="blue"
            >
              <IconPlayerPlay size={18} />
            </ActionIcon>
          </Tooltip>
          <Tooltip label="Descargar">
            <ActionIcon
              component="a"
              href={order.finalVideoUrl || "#"}
              download
              disabled={!isPlayable}
              variant="light"
              color="green"
            >
              <IconDownload size={18} />
            </ActionIcon>
          </Tooltip>
        </Group>
      </Table.Td>
    </Table.Tr>
  );
}
